  "footer.text": { en: "Part of <a href=\"https://quarcs-lab.github.io/metricsai/book/_book/index.html\"><strong>metricsAI</strong></a> · Chapter 2: Univariate Data Summary · by Carlos Mendez · <a href=\"https://github.com/quarcs-lab/metricsai\">GitHub</a>", es: "Parte de <a href=\"https://quarcs-lab.github.io/metricsai/book/_book/index.html\"><strong>metricsAI</strong></a> · Capítulo 2: Resumen de datos univariados · por Carlos Mendez · <a href=\"https://github.com/quarcs-lab/metricsai\">GitHub</a>" },
